class ConsistentHash {
  constructor(virtualCount = 500) {
    this.virtualCount = virtualCount;
    this.ring = [];          // [{ hash, node }] 按 hash 升序
    this.physicalNodes = new Set();
  }

  // 32 位字符串哈希：FNV 风格逐字符累加 + murmur finalizer 打散，分布比朴素 FNV 更均匀
  static hash(str) {
    let h = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) {
      h = Math.imul(h ^ str.charCodeAt(i), 0x01000193);
    }
    h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b);
    h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35);
    h ^= h >>> 16;
    return h >>> 0; // 无符号 32 位
  }

  addNode(node) {
    if (this.physicalNodes.has(node)) return;
    this.physicalNodes.add(node);
    for (let i = 0; i < this.virtualCount; i++) {
      const hash = ConsistentHash.hash(node + '#vn' + i);
      this.ring.push({ hash, node });
    }
    this.ring.sort((a, b) => a.hash - b.hash);
  }

  removeNode(node) {
    if (!this.physicalNodes.delete(node)) return;
    this.ring = this.ring.filter((slot) => slot.node !== node);
  }

  route(key) {
    if (!this.ring.length) return null;
    const h = ConsistentHash.hash(key);
    // 二分：第一个 hash >= h 的落点（顺时针上界）
    let lo = 0, hi = this.ring.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.ring[mid].hash < h) lo = mid + 1;
      else hi = mid;
    }
    const slot = this.ring[lo % this.ring.length]; // 回绕到环首
    return slot.node;
  }
}

// 测试
const ch = new ConsistentHash(500);
ch.addNode('node-A');
ch.addNode('node-B');
ch.addNode('node-C');
const N = 9000;
const keys = Array.from({ length: N }, (_, i) => 'order:' + i);
const dist = {};
for (const k of keys) {
  const node = ch.route(k);
  dist[node] = (dist[node] || 0) + 1;
}
console.log('删除前分布:', dist);
const ideal = N / 3;
const maxDev = Math.max(...Object.values(dist).map((c) => Math.abs(c - ideal) / ideal));
console.log('相对理想均分(3000)最大偏差:', (maxDev * 100).toFixed(1) + '%', maxDev < 0.1 ? '均衡(<=10%)' : '偏斜');
const before = new Map(keys.map((k) => [k, ch.route(k)]));
ch.removeNode('node-B');
let moved = 0, movedToOthers = true;
for (const k of keys) {
  const now = ch.route(k);
  if (before.get(k) !== now) {
    moved++;
    if (now === 'node-B') movedToOthers = false; // 不应再路由到已删节点
  }
}
console.log('删除 node-B 后迁移 key 数:', moved, '占比', (moved / N * 100).toFixed(1) + '%（理论约 1/3）');
console.log('迁移后无 key 落到已删节点:', movedToOthers);
console.log('删除后分布:', {
  A: keys.filter((k) => ch.route(k) === 'node-A').length,
  C: keys.filter((k) => ch.route(k) === 'node-C').length
});

class SnowflakeId {
  constructor(dataCenterId, workerId, epoch = 1704067200000n) {
    this.DATACENTER_BITS = 5n;
    this.WORKER_BITS = 5n;
    this.SEQUENCE_BITS = 12n;
    this.MAX_DATACENTER = (1n << this.DATACENTER_BITS) - 1n; // 31
    this.MAX_WORKER = (1n << this.WORKER_BITS) - 1n;         // 31
    this.MAX_SEQUENCE = (1n << this.SEQUENCE_BITS) - 1n;     // 4095
    this.WORKER_SHIFT = this.SEQUENCE_BITS;                  // 12
    this.DATACENTER_SHIFT = this.SEQUENCE_BITS + this.WORKER_BITS; // 17
    this.TIMESTAMP_SHIFT = this.DATACENTER_SHIFT + this.DATACENTER_BITS; // 22
    if (dataCenterId > this.MAX_DATACENTER || workerId > this.MAX_WORKER) {
      throw new Error('节点号超出位数范围');
    }
    this.dataCenterId = BigInt(dataCenterId);
    this.workerId = BigInt(workerId);
    this.epoch = epoch;
    this.sequence = 0n;
    this.lastTimestamp = -1n;
  }

  currentMillis() {
    return BigInt(Date.now());
  }

  nextId() {
    let timestamp = this.currentMillis();
    if (timestamp < this.lastTimestamp) {
      throw new Error('时钟回拨，拒绝生成 ID，回拨毫秒数=' + (this.lastTimestamp - timestamp));
    }
    if (timestamp === this.lastTimestamp) {
      this.sequence = (this.sequence + 1n) & this.MAX_SEQUENCE; // 溢出归零
      if (this.sequence === 0n) {
        // 本毫秒序列号耗尽，自旋等到下一毫秒
        while (timestamp <= this.lastTimestamp) timestamp = this.currentMillis();
      }
    } else {
      this.sequence = 0n;
    }
    this.lastTimestamp = timestamp;
    return ((timestamp - this.epoch) << this.TIMESTAMP_SHIFT)
      | (this.dataCenterId << this.DATACENTER_SHIFT)
      | (this.workerId << this.WORKER_SHIFT)
      | this.sequence;
  }
}

