const sf = new SnowflakeId(1, 2);
const ids = new Set();
let prev = -1n, increasing = true;
for (let i = 0; i < 5000; i++) {
  const id = sf.nextId();
  if (ids.has(id)) throw new Error('发现重复 ID');
  if (id <= prev) increasing = false;
  ids.add(id);
  prev = id;
}
console.log('生成数量:', ids.size);           // 5000
console.log('无重复:', ids.size === 5000);    // true
console.log('整体递增:', increasing);         // true（单线程同步生成）
console.log('首个 ID:', sf.nextId().toString());

// 模拟 3 个分片，每片订单按 (createTime, id) 升序
const shards = [
  [
    { id: 1, createTime: 100 }, { id: 4, createTime: 300 }, { id: 7, createTime: 500 }
  ],
  [
    { id: 2, createTime: 200 }, { id: 5, createTime: 400 }, { id: 8, createTime: 600 }
  ],
  [
    { id: 3, createTime: 250 }, { id: 6, createTime: 450 }, { id: 9, createTime: 700 }
  ]
];

// 游标之后的判定：先比 createTime，相同再比 id
function afterCursor(order, cursor) {
  if (!cursor) return true;
  if (order.createTime !== cursor.createTime) return order.createTime > cursor.createTime;
  return order.id > cursor.id;
}

function fetchPage(cursor, size) {
  // 每个分片只取游标之后的前 size 条（对应 SQL: WHERE (create_time,id) > ? LIMIT size）
  const candidates = [];
  for (const shard of shards) {
    let taken = 0;
    for (const order of shard) {
      if (afterCursor(order, cursor)) {
        candidates.push(order);
        if (++taken === size) break;
      }
    }
  }
  // 全局多路归并排序后取前 size 条
  candidates.sort((a, b) =>
    a.createTime - b.createTime || a.id - b.id
  );
  const page = candidates.slice(0, size);
  const nextCursor = page.length
    ? { createTime: page[page.length - 1].createTime, id: page[page.length - 1].id }
    : null;
  return { page, nextCursor };
}

// 测试：每页 3 条，连续翻 3 页
let cursor = null;
const all = [];
for (let p = 1; p <= 3; p++) {
